CREATE TABLE truss.source_epoch_registry (installation_id text NOT NULL COLLATE pg_catalog."C", source_epoch text NOT NULL COLLATE pg_catalog."C", target_incarnation text NOT NULL COLLATE pg_catalog."C", predecessor_epoch text COLLATE pg_catalog."C", transition_reason text NOT NULL COLLATE pg_catalog."C", profile_bytes bytea NOT NULL, evidence_bytes bytea NOT NULL, evidence_sha256 bytea GENERATED ALWAYS AS (pg_catalog.sha256(evidence_bytes)) STORED, PRIMARY KEY (installation_id, source_epoch), UNIQUE (source_epoch), FOREIGN KEY (installation_id) REFERENCES truss.installation_marker (installation_id), FOREIGN KEY (installation_id, predecessor_epoch) REFERENCES truss.source_epoch_registry (installation_id, source_epoch), CHECK (octet_length(source_epoch) BETWEEN 1 AND 256), CHECK (octet_length(target_incarnation) BETWEEN 1 AND 1024), CHECK (octet_length(profile_bytes) BETWEEN 1 AND 65536), CHECK (octet_length(evidence_bytes) BETWEEN 1 AND 1048576), CHECK (transition_reason IN ('initial', 'restore')), CHECK ((transition_reason = 'initial' AND predecessor_epoch IS NULL) OR (transition_reason = 'restore' AND predecessor_epoch IS NOT NULL)), CHECK (predecessor_epoch IS NULL OR predecessor_epoch <> source_epoch)); CREATE TABLE truss.source_epoch_current (singleton_id smallint PRIMARY KEY CHECK (singleton_id = 1), installation_id text NOT NULL COLLATE pg_catalog."C", source_epoch text NOT NULL COLLATE pg_catalog."C", FOREIGN KEY (installation_id, source_epoch) REFERENCES truss.source_epoch_registry (installation_id, source_epoch)); REVOKE ALL ON truss.source_epoch_registry, truss.source_epoch_current FROM public